python3 -c "
import urllib.request
import csv
import io
import re

url1 = 'https://docs.google.com/spreadsheets/d/1NQU2SGVykYL3n35NgzL78R0fszK0vt5yacNSV151wYI/export?format=csv&gid=1781095899'
rows1 = list(csv.reader(io.StringIO(urllib.request.urlopen(url1).read().decode('utf-8'))))

url2 = 'https://docs.google.com/spreadsheets/d/1NQU2SGVykYL3n35NgzL78R0fszK0vt5yacNSV151wYI/export?format=csv&gid=624666570'
rows2 = list(csv.reader(io.StringIO(urllib.request.urlopen(url2).read().decode('utf-8'))))

unpaid_ids = set()
for r in rows2[1:]:
    if len(r) > 0 and r[0].strip():
        nums = re.findall(r'\d+', r[0].strip())
        if nums:
            unpaid_ids.add(nums[-1])

missing_cases = []
for idx, r in enumerate(rows1[1:], start=2):
    if len(r) > 30:
        t_val = r[19].strip().upper()
        ae_val = r[30].strip().upper()
        if t_val in ['TRUE', '1', 'YES', '☑', 'CHECK']:
            if ae_val in ['FALSE', '0', '']:
                patient_id = None
                for cell in r:
                    m_id = re.search(r'(?:ID[:：]?\s*)?(\d{5,7})', cell)
                    if m_id:
                        patient_id = m_id.group(1)
                        break
                if patient_id and patient_id not in unpaid_ids:
                    shouzai = r[1] if len(r) > 1 else ''
                    info = r[5] if len(r) > 5 else ''
                    name = r[6] if len(r) > 6 else ''
                    missing_cases.append((idx, shouzai, patient_id, info, name))

for item in missing_cases[35:]:
    print(f'行 {item[0]} | 商材: {item[1]} | 患者ID: {item[2]} | 詳細: {item[3]} | 氏名/情報: {item[4]}')
"
